def finish_hierarchical_editing(conn_header: ConnHeader, params: FinishHierarchicalEditingParameters) -> dict:
    """
    Finishes the current hierarchical editing mode (Curtain Wall, Stair, Railing, Beam or Column): accept true keeps the
    changes (OK), accept false discards them (Cancel). The accept parameter is required, so changes are never discarded
    silently. Fails when Archicad is not in such an editing mode. Limitation: while an editing mode is open, Archicad
    refuses JSON commands with error 4001 (ongoing user input) before they run, so this command cannot leave a mode
    opened by EditHierarchicalElement or in Archicad (reported for Archicad 29); leave it in Archicad instead. Requires
    Archicad 27 or later.
    """
    return conn_header.core.post_tapir_command(
        command="FinishHierarchicalEditing", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


register_tool_for_dispatch(
    finish_hierarchical_editing,
    name="elements_finish_hierarchical_editing",
    title="FinishHierarchicalEditing",
    description=(
        "Finishes the current hierarchical editing mode (Curtain Wall, Stair, Railing, Beam or Column): accept true "
        "keeps the changes (OK), accept false discards them (Cancel). The accept parameter is required, so changes are "
        "never discarded silently. Fails when Archicad is not in such an editing mode. Limitation: while an editing "
        "mode is open, Archicad refuses JSON commands with error 4001 (ongoing user input) before they run, so this "
        "command cannot leave a mode opened by EditHierarchicalElement or in Archicad (reported for Archicad 29); "
        "leave it in Archicad instead. Requires Archicad 27 or later."
    ),
    params_model=FinishHierarchicalEditingParameters,
    output_model=FinishHierarchicalEditingResult,
    identity=("tapir", "FinishHierarchicalEditing"),
)


def get2_d_bounding_boxes(conn_header: ConnHeader, params: Get2DBoundingBoxesParameters) -> dict:
    """
    Get the 2D bounding box of elements as Archicad draws them, in the coordinates of the database the element is in:
    the floor plan, a section, a worksheet, a layout or a master layout. Works for 2D elements (Line, PolyLine, Arc,
    Hatch, Text, Label, Dimension, Drawing ...) as well as for model elements; a Text's box covers its drawn lines, a
    Drawing's box its frame with the title. The current window does not need to show the element. The output is the
    array of the bounding boxes respective to the input array of elements.
    """
    return conn_header.core.post_tapir_command(
        command="Get2DBoundingBoxes", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


