def get_cut_polygons_of_elements(conn_header: ConnHeader, params: GetCutPolygonsOfElementsParameters) -> dict:
    """
    Cuts each body of the 3D model of the given elements with a plane and returns, for each body, its building material,
    the area of the cut surface and its polygons (outline and holes) in 2D coordinates of the plane. From Archicad 28
    the 3D model is generated with separate components in a temporary sight, so a composite structure has one body per
    skin and the 3D window is not changed. Before Archicad 28 the bodies are those of the element's 3D model (a
    composite structure is one body) and their building materials are left out. The output is aligned with the input
    array of elements.
    """
    return conn_header.core.post_tapir_command(
        command="GetCutPolygonsOfElements", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


