def get_element_changes_since(conn_header: ConnHeader, params: GetElementChangesSinceParameters) -> dict:
    """
    Returns the new, modified and deleted elements between a state captured by CaptureElementState and either another
    captured state (toStateId) or the current state of the project. Scripts that keep an external copy of the model use
    it to sync only what changed instead of re-reading every element. The changes come from Archicad's element
    difference generator, which tracks the model elements: 2D elements such as texts, labels and hatches can be missing
    from the lists, so read those directly. Fails for a stateId that is unknown - never captured, released, or lost
    because the project was closed or Archicad restarted.
    """
    return conn_header.core.post_tapir_command(
        command="GetElementChangesSince", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


