def split_elements(conn_header: ConnHeader, params: SplitElementsParameters) -> dict:
    """
    Splits each given element along a line (the infinite line through its begin and end point, like Archicad's Split
    command). The original element keeps one part, copies of it (Drag a Copy, so they keep the layer, classifications,
    properties and every other setting) get the others; all are returned, the original first. Supports straight walls
    without doors, windows or openings, straight unslanted single segment beams without holes or openings, and lines
    (their arrows stay at the original ends), which are split in two, the original keeping the part from its begin
    point; and slabs, meshes without level lines or points, fills and single contour polylines, whose polygon (holes and
    arcs included) or points are cut along the line into one part per piece, the original keeping the largest piece (a
    polyline: the piece with its begin point). Slab edges keep their trim and side surface, the edges along the line are
    vertical; the corners a mesh gets on the line take their height from the edge they lie on. An element the line does
    not cross is reported as notCut, an unsupported one as an error naming its type. One undo step.
    """
    return conn_header.core.post_tapir_command(
        command="SplitElements", parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True)
    )


register_tool_for_dispatch(
    split_elements,
    name="elements_split_elements",
    title="SplitElements",
    description=(
        "Splits each given element along a line (the infinite line through its begin and end point, like Archicad's "
        "Split command). The original element keeps one part, copies of it (Drag a Copy, so they keep the layer, "
        "classifications, properties and every other setting) get the others; all are returned, the original first. "
        "Supports straight walls without doors, windows or openings, straight unslanted single segment beams without "
        "holes or openings, and lines (their arrows stay at the original ends), which are split in two, the original "
        "keeping the part from its begin point; and slabs, meshes without level lines or points, fills and single "
        "contour polylines, whose polygon (holes and arcs included) or points are cut along the line into one part per "
        "piece, the original keeping the largest piece (a polyline: the piece with its begin point). Slab edges keep "
        "their trim and side surface, the edges along the line are vertical; the corners a mesh gets on the line take "
        "their height from the edge they lie on. An element the line does not cross is reported as notCut, an "
        "unsupported one as an error naming its type. One undo step."
    ),
    params_model=SplitElementsParameters,
    output_model=SplitElementsResult,
    identity=("tapir", "SplitElements"),
)


def triangulate_polygons_of_elements(conn_header: ConnHeader, params: TriangulatePolygonsOfElementsParameters) -> dict:
    """
    Triangulates the plan polygon of the given elements, holes excluded, as Archicad does it: the outline of a Slab,
    Zone, Hatch or Mesh and the polygon of a Roof. Each triangle is given by the 2D coordinates of its three vertices.
    With convex: true, the faces of the 3D model of the elements (of any type) are decomposed into convex polygons
    instead, given by the 3D coordinates of their vertices. The output is aligned with the input array of elements; an
    element of another type gets an error item.
    """
    return conn_header.core.post_tapir_command(
        command="TriangulatePolygonsOfElements",
        parameters=params.model_dump(mode="json", by_alias=True, exclude_none=True),
    )


